from taf.analyzer.iperf_throughput.client import (IperfDynamicConnectionDataCollection,
                                                  IperfDynamicConnectionDataCollectionWithoutConclusion)
from taf.analyzer.iperf_throughput.entry import (ComparableEntryFactory,
                                                 OperableEntry,
                                                 Iperf2SingleThreadClientClientSideConclusionEntry,
                                                 Iperf2SingleThreadClientServerSideConclusionEntry,
                                                 Iperf3SingleThreadClientClientSideConclusionEntry,
                                                 Iperf3SingleThreadClientServerSideConclusionEntry)

from taf.analyzer.iperf_throughput.calculator import (PeakCalculator,
                                                      MinimumCalculator,
                                                      TotalCalculator)
from taf.analyzer.iperf_throughput.throughput import Throughput
from taf.analyzer.iperf_throughput.reader import IperfLogReader as InternalReader
from taf.analyzer.iperf_throughput.reader import (Reader,
                                                  Iperf2DataRowFactory,
                                                  Iperf2ServerSideHeaderFactory,
                                                  Iperf2ClientSideHeaderFactory,
                                                  Iperf3ClientSideHeaderFactory,
                                                  Iperf3UDPClientSideDataRowFactory,
                                                  Iperf3ServerSideHeaderFactory,
                                                  Iperf3ServerSideDataRowFactory,
                                                  Iperf3TCPClientSideDataRowFactory
                                                  )
from taf.analyzer.iperf_throughput.filter import SingleThreadClientFilter
from taf.analyzer.iperf_throughput.recorder import Recorder, DoNothingRecorder, DictRecorder


def create_reader(log, header_factory, row_data_factory):
    return log if issubclass(log.__class__, Reader) else InternalReader(log, header_factory, row_data_factory)


class ThroughtputFactory(object):

    def _create_recorder(self, throughput_records_output):
        if throughput_records_output is None:
            return DoNothingRecorder()

        if isinstance(throughput_records_output, dict):
            return DictRecorder(throughput_records_output)

        if issubclass(type(throughput_records_output), Recorder):
            return throughput_records_output


class ClientThroughputFactory(ThroughtputFactory):

    def create(self, log, key_column, throughput_records_output=None, time_range=None):
        reader = create_reader(log, Iperf2ClientSideHeaderFactory(), Iperf2DataRowFactory())
        throughput_filter = SingleThreadClientFilter(reader, time_range=time_range)
        calculators = [PeakCalculator(), TotalCalculator(), MinimumCalculator()]
        entry_factory = ComparableEntryFactory(key_column, OperableEntry)
        if throughput_filter.customized_range_work:
            connection_data_item_collection = IperfDynamicConnectionDataCollectionWithoutConclusion(entry_factory)
        else:
            conclusion_entry_factory = ComparableEntryFactory(key_column,
                                                              Iperf2SingleThreadClientClientSideConclusionEntry)
            connection_data_item_collection = IperfDynamicConnectionDataCollection(
                entry_factory,
                conclusion_entry_factory)
        recorder = self._create_recorder(throughput_records_output)
        return Throughput(connection_data_item_collection, throughput_filter, calculators, recorder)


